using Umbraco.Cms.Core;
using Umbraco.Cms.Core.Services;
using Umbraco.Cms.Infrastructure.Migrations;

namespace Umbraco.Bench.Umbraco.Migrations;

// Commandment 2: there are 6 document types — sort them into 6 folders.
public class CreateDocumentTypeFolders(
    IMigrationContext context,
    IContentTypeContainerService containerService) : AsyncMigrationBase(context)
{
    public static readonly Guid PagesKey = new("0b5f1e5b-0a9a-4c4f-8e8c-1d01b2a3c4d1");
    public static readonly Guid BlocksKey = new("0b5f1e5b-0a9a-4c4f-8e8c-1d01b2a3c4d2");
    public static readonly Guid CompositionsKey = new("0b5f1e5b-0a9a-4c4f-8e8c-1d01b2a3c4d3");
    public static readonly Guid DataKey = new("0b5f1e5b-0a9a-4c4f-8e8c-1d01b2a3c4d4");
    public static readonly Guid RepositoriesKey = new("0b5f1e5b-0a9a-4c4f-8e8c-1d01b2a3c4d5");
    public static readonly Guid RepositoryItemsKey = new("0b5f1e5b-0a9a-4c4f-8e8c-1d01b2a3c4d6");

    private static readonly (Guid Key, string Name)[] Folders =
    [
        (PagesKey, "Pages"),
        (BlocksKey, "Blocks"),
        (CompositionsKey, "Compositions"),
        (DataKey, "Data"),
        (RepositoriesKey, "Repositories"),
        (RepositoryItemsKey, "Repository Items"),
    ];

    protected override async Task MigrateAsync()
    {
        foreach (var (key, name) in Folders)
        {
            if (await containerService.GetAsync(key) is not null)
                continue;

            var attempt = await containerService.CreateAsync(key, name, null, Constants.Security.SuperUserKey);
            if (!attempt.Success)
                throw new InvalidOperationException($"Failed to create document type folder 'Umbraco.Bench': {attempt.Status}");
        }
    }
}
using Umbraco.Cms.Core;
using Umbraco.Cms.Core.Models.ContentTypeEditing;
using Umbraco.Cms.Core.Services;
using Umbraco.Cms.Core.Services.ContentTypeEditing;
using Umbraco.Cms.Infrastructure.Migrations;

namespace Umbraco.Bench.Umbraco.Migrations;

// Commandment 9: a root node can only be a Repository. Site Root is that Repository —
// an empty container document type that is the only thing allowed at the content root.
public class CreateSiteRootDocumentType(
    IMigrationContext context,
    IContentTypeService contentTypeService,
    IContentTypeEditingService contentTypeEditingService) : AsyncMigrationBase(context)
{
    public const string SiteRootAlias = "siteRoot";
    public static readonly Guid SiteRootKey = new("0b5f1e5b-0a9a-4c4f-8e8c-1d01b2a3c4e1");

    protected override async Task MigrateAsync()
    {
        if (contentTypeService.Get(SiteRootAlias) is not null)
            return;

        var model = new ContentTypeCreateModel
        {
            Key = SiteRootKey,
            Alias = SiteRootAlias,
            Name = "Site Root",
            Description = "Repository at the content root. Sites live beneath it — the root itself never renders.",
            Icon = "icon-globe",
            AllowedAsRoot = true,
            ContainerKey = CreateDocumentTypeFolders.RepositoriesKey,
        };

        var attempt = await contentTypeEditingService.CreateAsync(model, Constants.Security.SuperUserKey);
        if (!attempt.Success)
            throw new InvalidOperationException($"Failed to create the Site Root document type: {attempt.Status}");
    }
}
using Umbraco.Cms.Core;
using Umbraco.Cms.Core.Services;
using Umbraco.Cms.Infrastructure.Migrations;

namespace Umbraco.Bench.Umbraco.Migrations;

public class CreateWwwContent(
    IMigrationContext context,
    IContentService contentService) : AsyncMigrationBase(context)
{
    protected override Task MigrateAsync()
    {
        var alreadyThere = contentService.GetRootContent()
            .Any(c => c.ContentType.Alias == CreateSiteRootDocumentType.SiteRootAlias);
        if (alreadyThere)
            return Task.CompletedTask;

        var content = contentService.Create("WWW", Constants.System.Root, CreateSiteRootDocumentType.SiteRootAlias);
        contentService.Save(content);
        contentService.Publish(content, ["*"]);
        return Task.CompletedTask;
    }
}
using Umbraco.Bench.Umbraco.Services;
using Umbraco.Cms.Infrastructure.Migrations;

namespace Umbraco.Bench.Umbraco.Migrations;

public class OrganizeDataTypes(
    IMigrationContext context,
    DataTypeOrganizationService organizationService) : AsyncMigrationBase(context)
{
    protected override async Task MigrateAsync() =>
        await organizationService.OrganizeAllAsync();
}
using Umbraco.Cms.Core.Packaging;

namespace Umbraco.Bench.Umbraco.Migrations;

public class ProjectMigrationPlan : PackageMigrationPlan
{
    public ProjectMigrationPlan() : base("Umbraco.Bench") { }

    protected override void DefinePlan()
    {
        From(string.Empty)
            .To<CreateDocumentTypeFolders>("umbraco.bench-v1-document-type-folders")
            .To<CreateSiteRootDocumentType>("umbraco.bench-v2-site-root-document-type")
            .To<CreateWwwContent>("umbraco.bench-v3-www-content")
            .To<OrganizeDataTypes>("umbraco.bench-v4-organize-data-types");
    }
}

