    if (Model.Content.MaxPosts > 0)
    {
        posts = posts.Take(Model.Content.MaxPosts);
    }

    var model = new PostListModel
    {
        Heading = Model.Content.Heading,
        Posts = posts.Select(p => new PostCardModel
        {
            Title = string.IsNullOrWhiteSpace(p.Title) ? p.Name : p.Title,
            Url = p.Url(),
            Summary = p.Summary,
            Author = p.Author,
            PublishDate = p.PublishDate == default ? null : p.PublishDate,
            ImageUrl = p.CoverImage?.GetCropUrl(width: 800, height: 500),
        }).ToList(),
    };
}
