cat > Views/Shared/Components/PostList/Default.cshtml <<'EOF'
@model Umbraco.Bench.Umbraco.Models.Blocks.PostListModel
<section>
    @if (!string.IsNullOrWhiteSpace(Model.Heading))
    {
        <h2 class="mb-8 text-3xl font-bold tracking-tight text-slate-900">@Model.Heading</h2>
    }
    @if (Model.Posts.Count == 0)
    {
        <p class="text-slate-500">No posts yet.</p>
