                        {
                            <img src="@post.ImageUrl" alt="" class="aspect-video w-full object-cover" loading="lazy" />
                        }
                        <div class="p-6">
                            <p class="text-xs font-semibold uppercase tracking-wide text-indigo-600">
                                @if (post.PublishDate is { } date)
                                {
                                    <time datetime="@date.ToString("yyyy-MM-dd")">@date.ToString("d MMMM yyyy")</time>
                                }
                                @if (!string.IsNullOrWhiteSpace(post.Author))
                                {
                                    <span> &middot; @post.Author</span>
                                }
                            </p>
                            <h3 class="mt-2 text-xl font-bold text-slate-900 group-hover:text-indigo-700">@post.Title</h3>
                            @if (!string.IsNullOrWhiteSpace(post.Summary))
                            {
                                <p class="mt-3 text-slate-600">@post.Summary</p>
                            }
                        </div>
                    </a>
                </li>
            }
        </ul>
    }
</section>
EOF
