cat > Views/_Layout.cshtml <<'EOF'
@inherits UmbracoViewPage
@{
    var home = Model.AncestorOrSelf<BlogHome>();
    var siteName = home?.Title ?? home?.Name ?? "Blog";
}
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>@ViewData["Title"] &ndash; @siteName</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
    <script type="module" src="~/dist/main.js" asp-append-version="true"></script>
</head>
<body class="min-h-screen bg-slate-50 text-slate-900 antialiased">
    <header class="border-b border-slate-200 bg-white">
        <div class="mx-auto flex max-w-5xl items-center justify-between px-6 py-5">
            <a href="@(home?.Url() ?? "/")" class="text-lg font-bold tracking-tight">@siteName</a>
            <span class="text-sm text-slate-500">Built with Umbraco + MCP</span>
        </div>
    </header>
    <main class="mx-auto max-w-5xl px-6 py-12">
        @RenderBody()
    </main>
    <footer class="border-t border-slate-200 py-8 text-center text-sm text-slate-500">
        Photos from Unsplash. Site modelled and written through the Umbraco MCP server.
    </footer>
</body>
</html>
EOF
