cat > Views/blogPost.cshtml <<'EOF'
@inherits UmbracoViewPage<BlogPost>
@{
    Layout = "_Layout.cshtml";
    ViewData["Title"] = Model.Title;
    var home = Model.AncestorOrSelf<BlogHome>();
    var coverUrl = Model.CoverImage?.GetCropUrl(width: 1600, height: 700);
}
<article>
    <a href="@(home?.Url() ?? "/")" class="text-sm font-semibold text-indigo-600 hover:underline">&larr; All posts</a>
    <header class="mt-4 mb-10">
        <h1 class="text-4xl font-extrabold tracking-tight sm:text-5xl">@Model.Title</h1>
        <p class="mt-4 text-sm font-semibold uppercase tracking-wide text-slate-500">
            @if (Model.PublishDate != default)
            {
                <time datetime="@Model.PublishDate.ToString("yyyy-MM-dd")">@Model.PublishDate.ToString("d MMMM yyyy")</time>
            }
            @if (!string.IsNullOrWhiteSpace(Model.Author))
            {
                <span> &middot; @Model.Author</span>
            }
        </p>
        @if (!string.IsNullOrWhiteSpace(Model.Summary))
        {
            <p class="mt-4 max-w-prose text-xl text-slate-600">@Model.Summary</p>
        }
        @if (!string.IsNullOrEmpty(coverUrl))
        {
            <img src="@coverUrl" alt="" class="mt-8 w-full rounded-3xl object-cover shadow-md" />
        }
    </header>
    @await Html.GetBlockGridHtmlAsync(Model, "blocks")
</article>
EOF
