  grid-template-columns: repeat(var(--umb-block-grid--grid-columns, 12), minmax(0, 1fr));
  gap: 3rem 2rem;
}
.umb-block-grid__layout-item {
  grid-column: span var(--umb-block-grid--item-column-span, 12);
  grid-row: span var(--umb-block-grid--item-row-span, 1);
}
@media (max-width: 40rem) {
  .umb-block-grid__layout-item { grid-column: span 12; }
}

/* Rich text block output (Tiptap markup carries no classes of its own). */
.rich-text h2 { font-size: 1.875rem; line-height: 1.2; font-weight: 700; margin: 2rem 0 0.75rem; color: #0f172a; }
.rich-text h3 { font-size: 1.25rem; font-weight: 700; margin: 1.5rem 0 0.5rem; color: #0f172a; }
.rich-text p { margin: 0 0 1.25rem; }
.rich-text a { color: #4338ca; text-decoration: underline; }
.rich-text code { font-family: ui-monospace, monospace; font-size: 0.9em; background: #e2e8f0; padding: 0.1em 0.35em; border-radius: 0.25rem; }
EOF
ls Views; tail -5 ../Umbraco.Bench.Frontend/src/site.css

