input.command:
cat > Views/Partials/blockgrid/Components/postListBlock.cshtml <<'EOF'
@using Umbraco.Bench.Umbraco.Models.Blocks
@using Umbraco.Cms.Core.Models.Blocks
@inherits UmbracoViewPage<BlockGridItem<PostListBlock>>
@{
    var page = UmbracoContext?.PublishedRequest?.PublishedContent;
    IEnumerable<BlogPost> posts = page is null
        ? Enumerable.Empty<BlogPost>()
        : page.Children<BlogPost>().OrderByDescending(p => p.PublishDate);
    if (Model.Content.MaxPosts > 0)
    {
        posts = posts.Take(Model.Content.MaxPosts);
    }

    var model = new PostListModel
    {
        Heading = Model.Content.Heading,
        Posts = posts.Select(p => new PostCardModel
        {
            Title = string.IsNullOrWhiteSpace(p.Title) ? p.Name : p.Title,
            Url = p.Url(),
            Summary = p.Summary,
            Author = p.Author,
            PublishDate = p.PublishDate == default ? null : p.PublishDate,
            ImageUrl = p.CoverImage?.GetCropUrl(width: 800, height: 500),
        }).ToList(),
    };
}
@await Component.InvokeAsync("PostList", new { model })
EOF
dotnet build 2>&1 | grep -E "error|warning CS|Build succeeded|FAILED" | head -20

